struct RingBuffer {
    static constexpr int MAX_CAP = 1024;

    RingBuffer(int capacity) : cap(capacity < 1 ? 1 : (capacity > MAX_CAP ? MAX_CAP : capacity)), count(0), head(0), tail(0) {}

    bool push(int value) {
        if (full()) return false;
        buf[tail] = value;
        tail = (tail + 1) % cap;
        ++count;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = buf[head];
        head = (head + 1) % cap;
        --count;
        return true;
    }

    int  size() const { return count; }
    bool empty() const { return count == 0; }
    bool full() const { return count == cap; }

private:
    int buf[MAX_CAP];
    int cap;
    int count;
    int head;
    int tail;
};
