double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    // Layout:
    // W1: n_hidden * n_in, row-major: W1[j][k] = params[j*n_in + k]
    // b1: n_hidden, starts at params + n_hidden*n_in
    // W2: n_hidden, starts at params + n_hidden*n_in + n_hidden
    // b2: 1, starts at params + n_hidden*n_in + 2*n_hidden

    const int w1_size = n_hidden * n_in;
    const int b1_offset = w1_size;
    const int w2_offset = b1_offset + n_hidden;
    const int b2_offset = w2_offset + n_hidden;

    // Zero out grad
    for (int i = 0; i < w1_size + 2 * n_hidden + 1; ++i) {
        grad[i] = 0.0;
    }

    double total_loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        double y_s = y[s];

        // Compute hidden layer activations h[j]
        double h[n_hidden];
        for (int j = 0; j < n_hidden; ++j) {
            double sum = 0.0;
            for (int k = 0; k < n_in; ++k) {
                sum += params[j * n_in + k] * x[k];
            }
            sum += params[b1_offset + j];
            h[j] = tanh(sum);
        }

        // Compute z
        double z = 0.0;
        for (int j = 0; j < n_hidden; ++j) {
            z += params[w2_offset + j] * h[j];
        }
        z += params[b2_offset];

        // Compute p = sigmoid(z)
        double p;
        if (z >= 0) {
            p = 1.0 / (1.0 + exp(-z));
        } else {
            double ez = exp(z);
            p = ez / (1.0 + ez);
        }

        // Compute loss for this sample
        double eps = 1e-15;
        double p_clamped = p;
        if (p_clamped < eps) p_clamped = eps;
        if (p_clamped > 1.0 - eps) p_clamped = 1.0 - eps;
        double loss_s = -(y_s * log(p_clamped) + (1.0 - y_s) * log(1.0 - p_clamped));
        total_loss += loss_s;

        // Backprop: dL/dz = (p - y_s) / n_samples
        double dz = (p - y_s) / n_samples;

        // Gradient for b2
        grad[b2_offset] += dz;

        // Gradient for W2[j] and h[j]
        for (int j = 0; j < n_hidden; ++j) {
            grad[w2_offset + j] += dz * h[j];
            // dL/dh[j] = dz * W2[j]
            double dh_j = dz * params[w2_offset + j];
            // dL/d(pre-activation of h[j]) = dh_j * (1 - h[j]^2)
            double dpre_j = dh_j * (1.0 - h[j] * h[j]);

            // Gradient for b1[j]
            grad[b1_offset + j] += dpre_j;

            // Gradient for W1[j][k]
            for (int k = 0; k < n_in; ++k) {
                grad[j * n_in + k] += dpre_j * x[k];
            }
        }
    }

    return total_loss / n_samples;
}
