struct Tape {
    struct Node {
        double val;
        double grad;
        int parent1;
        int parent2;
        int op; // 0: constant, 1: input, 2: add, 3: mul, 4: sin, 5: exp
    };

    std::vector<Node> nodes;

    int constant(double v) {
        Node n;
        n.val = v;
        n.grad = 0.0;
        n.parent1 = -1;
        n.parent2 = -1;
        n.op = 0;
        nodes.push_back(n);
        return (int)nodes.size() - 1;
    }

    int input(double v) {
        Node n;
        n.val = v;
        n.grad = 0.0;
        n.parent1 = -1;
        n.parent2 = -1;
        n.op = 1;
        nodes.push_back(n);
        return (int)nodes.size() - 1;
    }

    int add(int a, int b) {
        Node n;
        n.val = nodes[a].val + nodes[b].val;
        n.grad = 0.0;
        n.parent1 = a;
        n.parent2 = b;
        n.op = 2;
        nodes.push_back(n);
        return (int)nodes.size() - 1;
    }

    int mul(int a, int b) {
        Node n;
        n.val = nodes[a].val * nodes[b].val;
        n.grad = 0.0;
        n.parent1 = a;
        n.parent2 = b;
        n.op = 3;
        nodes.push_back(n);
        return (int)nodes.size() - 1;
    }

    int sin_(int a) {
        Node n;
        n.val = std::sin(nodes[a].val);
        n.grad = 0.0;
        n.parent1 = a;
        n.parent2 = -1;
        n.op = 4;
        nodes.push_back(n);
        return (int)nodes.size() - 1;
    }

    int exp_(int a) {
        Node n;
        n.val = std::exp(nodes[a].val);
        n.grad = 0.0;
        n.parent1 = a;
        n.parent2 = -1;
        n.op = 5;
        nodes.push_back(n);
        return (int)nodes.size() - 1;
    }

    double value(int node) const {
        return nodes[node].val;
    }

    void backward(int root) {
        // Reset all gradients
        for (auto& n : nodes) {
            n.grad = 0.0;
        }
        // Seed the root
        nodes[root].grad = 1.0;
        // Sweep in reverse order (from last node to first)
        for (int i = (int)nodes.size() - 1; i >= 0; --i) {
            double g = nodes[i].grad;
            if (g == 0.0) continue;
            int p1 = nodes[i].parent1;
            int p2 = nodes[i].parent2;
            switch (nodes[i].op) {
                case 2: // add
                    if (p1 >= 0) nodes[p1].grad += g;
                    if (p2 >= 0) nodes[p2].grad += g;
                    break;
                case 3: // mul
                    if (p1 >= 0) nodes[p1].grad += g * nodes[p2].val;
                    if (p2 >= 0) nodes[p2].grad += g * nodes[p1].val;
                    break;
                case 4: // sin
                    if (p1 >= 0) nodes[p1].grad += g * std::cos(nodes[p1].val);
                    break;
                case 5: // exp
                    if (p1 >= 0) nodes[p1].grad += g * nodes[i].val;
                    break;
                default:
                    break;
            }
        }
    }

    double grad(int node) const {
        return nodes[node].grad;
    }
};
